"""Report prespecified v2 unit gates; never generate held-out inputs."""
from pathlib import Path
from collections import Counter
import csv,json,math,hashlib,re,subprocess,sys,time

A=Path(__file__).resolve().parent
REPO=A.parent.parent
ROOT=REPO.parent
OUT=ROOT/'revision_checks/v2'
ATTEMPT=Path(sys.argv[1]) if len(sys.argv)>1 else OUT/'unit_attempt_01'
GIT=r'C:\Users\nghare\.cache\codex-runtimes\codex-primary-runtime\dependencies\native\git\cmd\git.exe'
def git(*args):return subprocess.check_output([GIT,'-C',str(REPO),*args],encoding='utf-8').strip()
def load(path):return json.loads(path.read_text(encoding='utf-8'))
def sha(path):
    h=hashlib.sha256()
    with path.open('rb') as f:
        for block in iter(lambda:f.read(1048576),b''):h.update(block)
    return h.hexdigest()
def fmt(x):return f'{x:.10g}' if isinstance(x,float) else str(x)
def table(headers,rows):
    esc=lambda x:fmt(x).replace('|','\\|').replace('\n',' ')
    return '\n'.join(['| '+' | '.join(map(esc,headers))+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(map(esc,r))+' |' for r in rows])
def link(path,label=None):return f'[{label or path.name}](<{path.as_posix()}>)'
def main():
    started=time.monotonic();result=load(ATTEMPT/'unit_results.json');metadata=result['metadata'];commit=metadata['git_commit']
    assert git('branch','--show-current')=='v2-revision'
    assert git('rev-parse','HEAD')==commit and not git('status','--porcelain')
    assert (OUT/'PROTOCOL_v2.md').read_bytes()==(A/'PROTOCOL_v2.md').read_bytes()
    assert git('hash-object','src/bst_apc.m')==metadata['apc_source_blob']
    tag=git('tag','-l','v2.0')
    if result['status']=='STOP_UNIT_GATE':assert not tag
    with (ATTEMPT/'unit_trials.csv').open(encoding='utf-8',newline='') as f:rows=list(csv.DictReader(f))
    for row in rows:
        assert row['git_commit']==commit and row['matlab_version']==metadata['matlab_version']
        json.loads(row['apc_options_json']);json.loads(row['comparator_settings_json']);json.loads(row['generator_settings_json'])
    compat=load(ATTEMPT/'v1_compatibility.json');checks=load(ATTEMPT/'implementation_checks.json')
    assert compat['passed'] and checks['passed']
    assert not list(OUT.glob('heldout*'))
    stop=result.get('failed_gate','');gates=result['gates'];lines=[]
    def p(x=''):lines.append(x+'\n')
    p('# APC v2 fixed-specification unit-gate report')
    p(f'Branch `v2-revision`, from tag `v1.0` ({metadata["base_commit"]}). Candidate commit `{commit}`. '+
      ('The method-relevant unit gate failed. The workflow stopped before any held-out data generation; tag `v2.0` was not created.' if stop else 'All prespecified unit gates passed; no held-out data generated by this unit driver.'))
    p('## Factual summary (8 lines)')
    facts=[f'Candidate implementation and protocol were committed together at {commit}.',
        f'All five v1 compatibility cases exactly matched the v1.0 reference outputs and runInfo.',
        'Independent burst-trace/detection, pairwise-PPC, global-RNG and diagnostic-isolation checks passed.',
        f'Unit gates: a={gates["a"]}, b={gates["b"]}, c={gates["c"]}, d={gates["d"]}.',
        f'Completed unit trial rows: {len(rows)}.',
        f'First failed gate: {stop or "none"}.',
        'Held-out simulations, C1-C4 evaluation and H1/H2 figures were not run.',
        f'v2.0 tag: {tag or "not created"}; implementation bug fixes after testing: {len(result.get("implementation_bug_fixes",[]))}.']
    for i,x in enumerate(facts,1):p(f'{i}. {x}')
    p('## Committed specification and implementation')
    p('Requested-path protocol: '+link(OUT/'PROTOCOL_v2.md')+'. Identical committed protocol: '+link(A/'PROTOCOL_v2.md')+'. The complete user specification, including decision criteria verbatim, appears in both copies. The requested output folder is outside the Git repository, so the repository copy records the protocol in the candidate commit. No held-out results existed before this commit or this gate evaluation.')
    p('Source: '+link(REPO/'src/bst_apc.m')+'. Set version="v2" for the new mode. Missing version, version="v1" or version="v1.0" retains the previous calculations. The new path shares the unchanged v1 burst helpers, scans phase filters by event PPC, runs the original averages only as diagnostics, and scans amplitude by smoothed raw MVL. It reports unsmoothed raw MVL, conventional Ozkurt MVL, event PPC/z/p, burst counts/times, diagnostic flags and status.')
    p('PPC is (|sum(exp(i*phase))| squared - N)/(N*(N-1)), equivalent to the pairwise cosine average in [Vinck et al. (2010), equations 14-15](https://doi.org/10.1016/j.neuroimage.2010.01.073). The test independently checks that identity. Fourth-order Butterworth means fourth-order total bandpass before forward/reverse application, using the existing v1 SOS filter family. Parabolic interpolation uses raw PPC, not logarithms. The observed-event subset satisfies the 1/fP edge margin; independently jittering each of these events by uniform +/-1/fP keeps them inside the sampled record. The fixed event test uses 200 surrogates from a local, separately seeded mrg32k3a stream.')
    p('## Unit-test results')
    p(table(['Gate','Criterion','Result'],[
        ['a','High-SNR 8/120 Hz; |fP error|<=0.1 and |fA error|<=4',gates['a']],
        ['b','Same signal + uncoupled 11-Hz sine at 3x amplitude; |fP error|<=0.5',gates['b']],
        ['c','Poisson bursts: event p>0.05 in at least 8/10 fixed seeds',gates['c']],
        ['d','Run first 25 existing distractor level-0 trials; report without tuning',gates['d']]]))
    p(table(['Test','Trial','Seed','fP Hz','fA Hz','C_APC','Ozkurt MVL','PPC','Event z','Event p','Bursts','Usable bursts','Diagnostic flags','Status','Pass'],[
        [r['test'],r['trial_index'],r['seed'],float(r['recovered_fp_hz']),float(r['recovered_fa_hz']),float(r['C_APC']),float(r['ozkurt_mvl']),float(r['event_ppc']),float(r['event_z']),float(r['event_p']),r['burst_count'],r['usable_burst_count'],r['diagnostic_flags'],r['status'],r['passed']] for r in rows]))
    if stop:
        failed=[r for r in rows if r['test']==stop]
        if stop in ['a','b']:
            r=failed[-1]
            p(f'Gate {stop}: recovered fP={float(r["recovered_fp_hz"]):.17g} Hz, |error|={abs(float(r["recovered_fp_hz"])-8):.17g} Hz; recovered fA={float(r["recovered_fa_hz"]):.17g} Hz, |error|={abs(float(r["recovered_fa_hz"])-120):.17g} Hz. Status={r["status"]}. The gate was evaluated against its precommitted tolerances; no signal, parameter, frequency grid or code was changed after observing it.')
        else:p('Gate c returned p>0.05 on '+str(sum(float(r['event_p'])>.05 for r in failed))+'/10 seeds; the required count is at least eight.')
        p('Subsequent unit tests were not run because the precommitted sequential stopping rule applies at the first performance-gate failure. The implementation-invariant checks passed; no implementation bug was identified or repaired. No parameter tuning or second unit attempt was performed.')
    p('Completed per-trial data: '+link(ATTEMPT/'unit_trials.csv')+'. Full gate record: '+link(ATTEMPT/'unit_results.json')+'. Five-case v1 check: '+link(ATTEMPT/'v1_compatibility.json')+'. Implementation checks: '+link(ATTEMPT/'implementation_checks.json')+'.')
    for name in ['a','b']:
        path=ATTEMPT/f'unit_{name}_ppc_curve.csv'
        if path.exists():p(f'Unit {name} full candidate PPC curve: '+link(path)+'. Saved signal, components, intermediate arrays and surrogate scores: '+link(ATTEMPT/f'unit_{name}.mat')+'.')
    p('The unit profile was fixed before any result: six seconds, fs=500 Hz, 8-Hz sine amplitude 1, .08 baseline 120-Hz carrier, Gaussian bursts with sigma=.028 s, amplitude=1.3*.60 and .010-s timing jitter centered on physical troughs, mixed pink/white noise at 20 dB SNR, no 96-Hz component. Signal seed=20260618. Unit b retains the identical signal/noise and adds a 3x 11-Hz sine with the separate predeclared phase stream. Unit-c seeds and streams and the unit-d selection were also fixed in the committed protocol.')
    p('## Held-out evaluation and decision criteria')
    p('No held-out data were generated. The requested per-scenario recovery tables, null AUCs, event-test rejection rates and H1/H2 figures therefore have no values. Missing results are not scored as criterion failures.')
    p(table(['Criterion','Status','Numbers'],[[k,'NOT EVALUATED','Held-out generation blocked by unit gate '+stop] for k in ['C1','C2','C3','C4']]))
    p('Decision criteria are retained verbatim in the protocol. The candidate has not been designated APC v2.0 or frozen with that tag.')
    p('## Runtime, fixes and deviations')
    p(f'Unit-driver elapsed time: {result["elapsed_seconds"]:.6f} seconds, excluding MATLAB startup. One computation thread. MATLAB {metadata["matlab_version"]}. Full MATLAB log: '+link(OUT/'unit_attempt_01_matlab.log')+'.')
    p('Implementation bugs fixed after unit testing: '+('none.' if not result.get('implementation_bug_fixes') else json.dumps(result['implementation_bug_fixes'])) )
    p('Tooling deviations: '+('none during the unit execution.' if not result.get('tooling_deviations') else json.dumps(result['tooling_deviations']))+' MATLAB startup may report pre-existing missing Brainstorm paths; the driver verifies the exact repository APC source before execution. The protocol mirror is the documented path-layout accommodation. Every Python text read/write explicitly uses UTF-8.')
    p('Stopped work: remaining unit gates (if any), v2.0 tagging, held-out data generation/evaluation, criterion decisions and held-out figures. The failed method-relevant gate is the reason for stopping. The source remains at the committed candidate; earlier commits, tags and saved results were not rewritten.')
    p('## Full provenance')
    p('Trial CSVs and MAT checkpoints include commit, MATLAB version, complete normalized APC options, full fixed comparator settings, signal/surrogate seeds, generator settings and diagnostic arrays. Output hashes: '+link(OUT/'output_manifest.json')+'.')
    p('```json\n'+json.dumps(metadata,indent=2)+'\n```')
    report=OUT/'RESULTS_v2.md';report.write_text('\n'.join(lines),encoding='utf-8')
    for target in re.findall(r'\]\(<([^>]+)>\)',report.read_text(encoding='utf-8')):
        if target.endswith('/output_manifest.json'):continue
        assert Path(target).exists(),target
    protected={'v1_tag':metadata['base_commit'],'v2_candidate':commit,'v2_tag':tag or None,
        'heldout_generated':False,'protocol_copies_identical':True,'metadata':metadata,
        'files':{str(p):sha(p) for p in sorted(OUT.rglob('*')) if p.is_file() and '__pycache__' not in p.parts and p.name!='output_manifest.json'}}
    (OUT/'output_manifest.json').write_text(json.dumps(protected,indent=2),encoding='utf-8')
    print(json.dumps({'report':str(report),'status':result['status'],'failed_gate':stop,'rows':len(rows),'commit':commit,'build_seconds':time.monotonic()-started}))

if __name__=='__main__':main()
